//! JSON Schema for [`crate::Document`].

use crate::Result;
use crate::program::Document;

/// JSON Schema (draft 2020-12) for [`Document`], generated by schemars.
///
/// The committed copy is `docs/schema/campanion-ir-1.schema.json`.
pub fn json_schema() -> Result<serde_json::Value> {
    serde_json::to_value(schemars::schema_for!(Document)).map_err(|err| crate::IrError::Json(err.to_string()))
}
